mapper.select:
SELECT COUNT(*) FROM challenge
AND (challenge_title LIKE CONCAT('%', #{searchKeyword}, '%') OR challenge_content LIKE CONCAT('%', #{searchKeyword}, '%'))
AND challenge_category_code = #{categoryCode}

SELECT challenge_code, created_at, challenge_title, challenge_content, host_user, recruitment_num, start_date, end_date, xp, thumbnail_url, challenge_category_code, challenge_status FROM challenge
AND (challenge_title LIKE CONCAT('%', #{searchKeyword}, '%') OR challenge_content LIKE CONCAT('%', #{searchKeyword}, '%'))
AND challenge_category_code = #{categoryCode}
ORDER BY created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM challenge_part
WHERE challenge_code = #{challengeCode}

mapper.update:
UPDATE challenge
challenge_title = #{update.challengeTitle}, challenge_content = #{update.challengeContent}, recruitment_num = #{update.recruitmentNum}, start_date = #{update.startDate}, end_date = #{update.endDate}, xp = #{update.xp}, thumbnail_url = #{update.thumbnailUrl}, challenge_category_code = #{update.challengeCategoryCode},
WHERE challenge_code = #{challengeCode}

UPDATE challenge
SET challenge_status = #{status}
WHERE challenge_code = #{challengeCode}
